-- Isolated native proof fixture only. NOT a production migration or integrated source capability.
-- Existing capture/permit interfaces remain unchanged and reject this two-table publication.
begin;
set role mip_temporal_registry_owner;
create table mip_temporal.stream_markers(
 marker_id uuid primary key,
 epoch uuid not null,
 creator_xid xid8 not null default pg_current_xact_id()
);
alter table mip_temporal.stream_markers enable row level security;
alter table mip_temporal.stream_markers force row level security;
-- No recorder/gateway/worker table policy or grant. Synthetic CI administrator supplies markers.
create policy registry on mip_temporal.stream_markers to mip_temporal_registry_owner using(true) with check(true);
reset role;
create trigger immutable_rows before update or delete on mip_temporal.stream_markers
 for each row execute function mip_hypothesis.reject_mutation();
create trigger immutable_table before truncate on mip_temporal.stream_markers
 for each statement execute function mip_hypothesis.reject_mutation();
revoke all on mip_temporal.stream_markers from public,anon,authenticated,service_role,mip_temporal_recorder,mip_temporal_ack_gateway,mip_comparison_worker_v1;
commit;

// Isolated native-boundary proof. Not wired to source permits or production consumers.
import {createHash} from 'node:crypto'
const uid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/
const deny=()=>{throw Error('mip_marker_boundary_denied')}
const lsn=n=>(n>>32n).toString(16).toUpperCase()+'/'+(n&4294967295n).toString(16).toUpperCase()
function id(v){if(typeof v!=='string'||!uid.test(v))deny();return v}
function relation(v){if(typeof v!=='string'||!/^[1-9][0-9]{0,9}$/.test(v)||BigInt(v)>4294967295n)deny();return v}
function reader(b){
 if(!Buffer.isBuffer(b)||b.length===0||b.length>4096)deny()
 let p=0
 const take=n=>{if(!Number.isSafeInteger(n)||n<0||p+n>b.length)deny();const v=b.subarray(p,p+n);p+=n;return v}
 return {u8:()=>take(1)[0],u16:()=>take(2).readUInt16BE(),u32:()=>take(4).readUInt32BE(),
 u64:()=>take(8).readBigUInt64BE(),i64:()=>take(8).readBigInt64BE(),
 str:()=>{const end=b.indexOf(0,p);if(end<0||end-p>100)deny();const v=take(end-p);take(1);if(v.some(x=>x>127))deny();return v.toString('ascii')},
 text:n=>{if(n>100)deny();const v=take(n);if(v.some(x=>x>127||x===0))deny();return v.toString('ascii')},
 end:()=>{if(p!==b.length)deny()}}
}
export function decodeMarkerBoundary(frames,{relationId,observationEpoch,markerId}){
 relation(relationId);id(observationEpoch);id(markerId)
 // Exactly one native marker-only transaction; no arbitrary empty or mixed transaction.
 if(!Array.isArray(frames)||frames.length!==4)deny()
 let total=0,begin,marker,ending
 for(let index=0;index<4;index++){
  total+=frames[index]?.length??0;if(total>16384)deny()
  const r=reader(frames[index]),kind=r.u8()
  if(index===0){
   if(kind!==66)deny()
   begin={commit:r.u64(),time:r.i64(),xid:r.u32()}
   if(begin.commit===0n||begin.xid===0)deny()
  }else if(index===1){
   if(kind!==82||String(r.u32())!==relationId||r.str()!=='mip_temporal'||r.str()!=='stream_markers'||r.u8()!==100||r.u16()!==3)deny()
   for(const [name,type,flag] of [['marker_id',2950,1],['epoch',2950,0],['creator_xid',5069,0]])
    if(r.u8()!==flag||r.str()!==name||r.u32()!==type||r.u32()!==4294967295)deny()
  }else if(index===2){
   if(kind!==73||String(r.u32())!==relationId||r.u8()!==78||r.u16()!==3)deny()
   const values=[]
   for(let i=0;i<3;i++){if(r.u8()!==116)deny();values.push(r.text(r.u32()))}
   if(values[0]!==markerId||values[1]!==observationEpoch||!/^[1-9][0-9]{0,19}$/.test(values[2]))deny()
   const full=BigInt(values[2])
   if(full>18446744073709551615n||(full&4294967295n)!==BigInt(begin.xid))deny()
   marker={marker_id:markerId,observation_epoch:observationEpoch,creator_xid:values[2]}
  }else{
   if(kind!==67||r.u8()!==0)deny()
   const commit=r.u64(),end=r.u64(),time=r.i64()
   if(commit!==begin.commit||time!==begin.time||end<=commit)deny()
   ending=end
  }
  r.end()
 }
 return {schema:'mip_marker_boundary_v1',relation_id:relationId,...marker,
  commit_lsn:lsn(begin.commit),end_lsn:lsn(ending),xid:String(begin.xid),
  // Preserve source timestamp bytes without interpreting them as historical qualification.
  commit_time_pg_microseconds:begin.time.toString(),historical_time_qualified:false}
}
export async function retainMarkerBoundary({frames,relationId,observationEpoch,markerId,context,journal}){
 if(!context||Object.getPrototypeOf(context)!==Object.prototype||Object.keys(context).sort().join('|')!=='source_id|stream_epoch'||
 typeof journal?.putOnce!=='function'||typeof journal?.get!=='function')deny()
 const source=id(context.source_id),stream=id(context.stream_epoch)
 const boundary=decodeMarkerBoundary(frames,{relationId,observationEpoch,markerId})
 // Own all bytes and identities before async custody calls.
 const hex=frames.map(v=>v.toString('hex'))
 const envelope={schema:'mip_marker_delivery_proof_v1',source_id:source,stream_epoch:stream,boundary,
  frame_hash:createHash('sha256').update(hex.join('\n')).digest('hex'),frames:hex,authority_integrated:false}
 const fixedEnd=boundary.end_lsn
 const key='marker-proof-v1:'+source+':'+stream+':'+markerId,exact=JSON.stringify(envelope)
 const receipt=await journal.putOnce(key,envelope)
 if(receipt?.committed!==true||JSON.stringify(await journal.get(key))!==exact)throw Error('mip_marker_boundary_not_durable')
 // This proof intentionally has no acknowledge/advance capability.
 return {state:'durable_marker_boundary_proof',key,end_lsn:fixedEnd,
  authority_integrated:false,historical_time_qualified:false}
}

import test from 'node:test'
import assert from 'node:assert/strict'
import {frames,epoch} from './hypothesisPgoutputFixture.mjs'
import {decodeMarkerBoundary,retainMarkerBoundary} from '../supabase/qualification/hypothesis-assessments/pgoutputBoundaryRecorder.mjs'
const options={relationId:'42',observationEpoch:epoch,markerId:epoch}
const context={source_id:epoch,stream_epoch:'22222222-2222-4222-8222-222222222222'}
const markerFrames=(args={})=>{
 const result=frames(args)
 result[1]=Buffer.from(result[1].toString('latin1').replace('mip_hypothesis','mip_temporal').replace('revision_transactions','stream_markers').replace('revision_id','marker_id'),'latin1')
 return result
}
const journal=()=>{const entries=new Map();return {entries,
 putOnce:async(k,v)=>{const text=JSON.stringify(v);if(entries.has(k)&&entries.get(k)!==text)throw Error('conflict');entries.set(k,text);return {committed:true}},
 get:async k=>entries.has(k)?JSON.parse(entries.get(k)):null}}
test('marker proof is a distinct native transaction with exact epoch, relation, xid and endpoint',()=>{
 const b=decodeMarkerBoundary(markerFrames(),options)
 assert.equal(b.end_lsn,'0/3FC');assert.equal(b.creator_xid,'4294967303')
 assert.equal(b.historical_time_qualified,false);assert.equal(Object.hasOwn(b,'revisions'),false)
 for(const [data,opt] of [
  [[],options],[frames(),options],[markerFrames().slice(0,-1),options],
  [[...markerFrames(),...markerFrames()],options],
  [markerFrames(),{...options,markerId:context.stream_epoch}],
  [markerFrames(),{...options,observationEpoch:context.stream_epoch}],
  [markerFrames(),{...options,relationId:'43'}],
  [markerFrames({full:'4294967304'}),options],
  [markerFrames({end:999}),options]
 ])assert.throws(()=>decodeMarkerBoundary(data,opt),/mip_marker_boundary_denied/)
})
test('mutation, logical message, extra tuple, trailing bytes and commit mismatch fail closed',()=>{
 for(const index of [0,1,2,3]){
  const data=markerFrames();data[index]=Buffer.concat([data[index],Buffer.from([0])])
  assert.throws(()=>decodeMarkerBoundary(data,options))
 }
 for(const kind of [77,85,68,84,83]){
  const data=markerFrames();data[2][0]=kind
  assert.throws(()=>decodeMarkerBoundary(data,options))
 }
 const data=markerFrames();data[3][9]^=1
 assert.throws(()=>decodeMarkerBoundary(data,options))
})
test('retention requires committed exact readback, immutable retry and never acknowledges',async()=>{
 const j=journal(),data=markerFrames()
 const args={...options,context,frames:data,journal:j}
 const result=await retainMarkerBoundary(args)
 assert.equal(result.state,'durable_marker_boundary_proof')
 assert.equal(result.authority_integrated,false);assert.equal(result.historical_time_qualified,false)
 assert.deepEqual(await retainMarkerBoundary(args),result)
 await assert.rejects(()=>retainMarkerBoundary({...args,frames:markerFrames({time:842529600123457n})}),/conflict/)
 await assert.rejects(()=>retainMarkerBoundary({...args,journal:{putOnce:async()=>({committed:false}),get:j.get}}),/not_durable/)
 await assert.rejects(()=>retainMarkerBoundary({...args,journal:{putOnce:j.putOnce,get:async()=>null}}),/not_durable/)
})
test('caller mutation during custody cannot change retained source or native transcript',async()=>{
 const j=journal(),data=markerFrames(),scope={...context}
 const result=await retainMarkerBoundary({...options,context:scope,frames:data,journal:{
  putOnce:async(k,v)=>{scope.source_id=context.stream_epoch;data[0].fill(0);return j.putOnce(k,v)},get:j.get}})
 assert.equal((await j.get(result.key)).source_id,context.source_id)
 assert.equal((await j.get(result.key)).frames[0][0],'4')
})

test('custody adapter mutation cannot alter the returned endpoint after retaining original bytes',async()=>{
 const j=journal()
 let adapterObject
 const result=await retainMarkerBoundary({...options,context,frames:markerFrames(),journal:{
  putOnce:async(k,v)=>{adapterObject=v;const receipt=await j.putOnce(k,v);v.boundary.end_lsn='F/FFFFFF';return receipt},
  get:async k=>{adapterObject.boundary.end_lsn='E/EEEEEE';return j.get(k)}
 }})
 const retained=await j.get(result.key)
 assert.equal(result.end_lsn,retained.boundary.end_lsn)
 assert.equal(result.end_lsn,'0/3FC')
})

// Native proof only. Administrative marker emission/advance here is confined to disposable CI.
// Source authority, registration and covered-consumer integration are explicitly not implemented.
import assert from 'node:assert/strict'
import {readFile} from 'node:fs/promises'
import {randomUUID,randomBytes} from 'node:crypto'
import {quote as q,transport} from '../integrated/transport.mjs'
import {producerRole} from '../integrated/fixture.mjs'
import {hold} from './fixture.mjs'
import {encryptedRemoteJournal} from '../../supabase/qualification/mip-cutover-authority/brokerSession.js'
import {decodeRevisionCommits,recordPgoutputBatch} from '../../supabase/qualification/hypothesis-assessments/pgoutputRecorder.mjs'
import {decodeMarkerBoundary,retainMarkerBoundary} from '../../supabase/qualification/hypothesis-assessments/pgoutputBoundaryRecorder.mjs'
export async function markerBoundaryCases(t,f,{runWorker,holdRevision}){
 await f.admin(await readFile(new URL('../../supabase/qualification/hypothesis-assessments/021_stream_boundary_proof.sql',import.meta.url),'utf8'))
 const relationId=await f.admin("select 'mip_temporal.stream_markers'::regclass::oid::text")
 const revisionRelation=await f.admin("select 'mip_hypothesis.revision_transactions'::regclass::oid::text")
 const runtime='synthetic-marker-'+randomUUID(),mapping=randomUUID(),material={version:'synthetic-marker-v1',key:randomBytes(32)}
 await f.admin('insert into mip_identity.mapping_versions select '+q(mapping)+','+q(runtime)+
  ',principal,issuer,audience,'+q(runtime+':'+producerRole)+',key_revision,max_lifetime_seconds,approval_ref from mip_identity.mapping_versions where revision='+
  q(f.mappings['runtime-a'+producerRole])+';insert into mip_identity.mapping_heads values('+[runtime,producerRole,mapping].map(q).join(',')+',true);')
 let session=await f.issue(runtime,producerRole)
 const journal=()=>encryptedRemoteJournal({sql:transport(f.db,'mip_journal_gateway_v2'),session,
  keyProvider:r=>{if(r!==runtime)throw Error('wrong_runtime');return material}})
 const markerSql=id=>'insert into mip_temporal.stream_markers(marker_id,epoch) values('+[id,f.observationEpoch].map(q).join(',')+');'
 async function stream(t){
  const suffix=randomUUID().replaceAll('-',''),pub='synthetic_marker_'+suffix,slot='synthetic_marker_'+suffix
  await f.admin('create publication '+pub+' for table mip_hypothesis.revision_transactions(revision_id,epoch,creator_xid),mip_temporal.stream_markers(marker_id,epoch,creator_xid) with (publish=\'insert\');')
  await f.admin('select slot_name from pg_create_logical_replication_slot('+[slot,'pgoutput'].map(q).join(',')+');')
  t.after(()=>f.admin('select pg_drop_replication_slot(slot_name) from pg_replication_slots where slot_name='+q(slot)+';drop publication '+pub+';'))
  const context={source_id:randomUUID(),stream_epoch:randomUUID()}
  const confirmed=()=>f.admin('select confirmed_flush_lsn::text from pg_replication_slots where slot_name='+q(slot))
  const peek=async()=>JSON.parse(await f.admin("select coalesce(jsonb_agg(encode(data,'hex') order by sequence),'[]') from pg_logical_slot_peek_binary_changes("+
   q(slot)+",null,1,'proto_version','1','publication_names',"+q(pub)+",'binary','false','streaming','false','messages','false') with ordinality as c(lsn,xid,data,sequence);")).map(x=>Buffer.from(x,'hex'))
  const advance=end=>f.admin('select end_lsn::text from pg_replication_slot_advance('+[slot,end].map(q).join(',')+');')
  const emit=id=>f.admin(markerSql(id))
  const retain=(frames,id,j=journal())=>retainMarkerBoundary({frames,markerId:id,relationId,observationEpoch:f.observationEpoch,context,journal:j})
  return {pub,slot,context,confirmed,peek,advance,emit,retain}
 }
 await t.test('unrelated WAL and empty peek never prove coverage; committed native marker does',async t=>{
  const b=await stream(t),before=await b.confirmed(),id=randomUUID()
  await f.admin('create table public.synthetic_marker_unrelated(id uuid);insert into public.synthetic_marker_unrelated values(gen_random_uuid());')
  assert.equal((await b.peek()).length,0);assert.equal(await b.confirmed(),before)
  await b.emit(id)
  const data=await b.peek(),proof=decodeMarkerBoundary(data,{relationId,observationEpoch:f.observationEpoch,markerId:id})
  assert.equal(await b.confirmed(),before)
  await assert.rejects(()=>b.retain(data,id,{putOnce:async()=>({committed:true}),get:async()=>null}),/not_durable/)
  assert.equal(await b.confirmed(),before)
  const saved=await b.retain(data,id)
  assert.equal(saved.end_lsn,proof.end_lsn);assert.equal(saved.historical_time_qualified,false)
  assert.equal(await b.advance(saved.end_lsn),saved.end_lsn)
  assert.equal((await b.peek()).length,0)
  assert.deepEqual(await b.retain(data,id),saved)
 })
 await t.test('open actual revision transaction survives consuming a later marker and decodes after commit',async t=>{
  const b=await stream(t),pending=await holdRevision(),id=randomUUID()
  let ended=false
  try{
   await b.emit(id)
   const data=await b.peek(),saved=await b.retain(data,id)
   await b.advance(saved.end_lsn)
   assert.equal((await b.peek()).length,0)
   await pending.finish(true);ended=true
   const revisions=decodeRevisionCommits(await b.peek(),{relationId:revisionRelation,observationEpoch:f.observationEpoch})
   assert.equal(revisions.length,1)
   const expected=JSON.parse(await f.admin('select jsonb_agg(id::text) from mip_hypothesis.revisions where investigation_id='+q(pending.investigationId)))
   assert.deepEqual(revisions[0].input.revisions.map(r=>r.revision_id),expected)
   assert.notEqual(revisions[0].end_lsn,saved.end_lsn)
   await recordPgoutputBatch({frames:await b.peek(),relationId:revisionRelation,observationEpoch:f.observationEpoch,context:b.context,journal:journal(),
    acknowledge:p=>b.advance(p.end_lsn)})
   assert.equal((await b.peek()).length,0)
  }finally{if(!ended)await pending.finish(false)}
 })
 await t.test('rolled-back actual revision and rolled-back marker produce no published transaction',async t=>{
  const b=await stream(t),before=await b.confirmed(),pending=await holdRevision()
  await pending.finish(false)
  const id=randomUUID(),marker=await hold(f.db,markerSql(id))
  assert.equal((await b.peek()).length,0);await marker.finish(false)
  assert.equal((await b.peek()).length,0);assert.equal(await b.confirmed(),before)
  await b.emit(randomUUID())
  assert.equal((await b.peek()).length,4)
 })
 await t.test('intervening revision must be retained before requested marker and cannot decode as marker',async t=>{
  const b=await stream(t),v=await f.investigation()
  await v.captureGeneration();await runWorker(v)
  const id=randomUUID();await b.emit(id)
  const first=await b.peek(),before=await b.confirmed()
  await assert.rejects(()=>b.retain(first,id),/mip_marker_boundary_denied/)
  assert.equal(await b.confirmed(),before)
  await recordPgoutputBatch({frames:first,relationId:revisionRelation,observationEpoch:f.observationEpoch,context:b.context,journal:journal(),
   acknowledge:p=>b.advance(p.end_lsn)})
  const next=await b.peek(),saved=await b.retain(next,id)
  await b.advance(saved.end_lsn);assert.equal((await b.peek()).length,0)
 })
 await t.test('fixture exact publication and no gateway marker grants; native source integration stays closed',async t=>{
  const b=await stream(t)
  const tables=JSON.parse(await f.admin("select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'columns',attnames,'filter',rowfilter) order by schemaname,tablename) from pg_publication_tables where pubname="+q(b.pub)))
  assert.deepEqual(tables,[
   {schema:'mip_hypothesis',table:'revision_transactions',columns:['revision_id','epoch','creator_xid'],filter:null},
   {schema:'mip_temporal',table:'stream_markers',columns:['marker_id','epoch','creator_xid'],filter:null}])
  for(const role of ['mip_temporal_recorder','mip_temporal_ack_gateway','mip_comparison_worker_v1','service_role'])
   await assert.rejects(()=>f.admin('set session authorization '+role+';'+markerSql(randomUUID())),/mip_database_denied_42501/)
  assert.equal(await f.admin("select relrowsecurity and relforcerowsecurity from pg_class where oid='mip_temporal.stream_markers'::regclass"),'t')
  const definition=await f.admin("select pg_get_functiondef('mip_temporal.check_stream(uuid,uuid)'::regprocedure)")
  assert.ok(definition.includes(')<>1')) // Existing one-table source contract is intentionally not broadened.
 })
 await t.test('slot loss does not erase retained proof or grant source-recovery authority',async t=>{
  const b=await stream(t),id=randomUUID();await b.emit(id)
  const data=await b.peek(),saved=await b.retain(data,id)
  await f.admin('select pg_drop_replication_slot('+q(b.slot)+');')
  await assert.rejects(()=>b.advance(saved.end_lsn))
  session=await f.issue(runtime,producerRole)
  assert.deepEqual(await b.retain(data,id),saved)
  assert.equal(saved.authority_integrated,false)
 })
 await t.test('revoked journal mapping blocks retention; source WAL remains unacknowledged',async t=>{
  const b=await stream(t),id=randomUUID();await b.emit(id)
  const data=await b.peek(),before=await b.confirmed()
  await f.admin('update mip_identity.mapping_heads set active=false where runtime='+q(runtime))
  await assert.rejects(()=>b.retain(data,id))
  assert.equal(await b.confirmed(),before)
  assert.equal((await b.peek()).length,4)
 })
}

import {markerBoundaryCases} from './markerBoundaryCases.mjs'
import {continuityCases} from './continuityCases.mjs'
import {bootstrapCases} from './bootstrapCases.mjs'
import {pgoutputCases} from './pgoutputCases.mjs'
import {createSupabaseHypothesisAuthenticator} from '../../supabase/qualification/hypothesis-assessments/supabaseAuthenticator.mjs'
import {syntheticAuthProvider} from '../../tests/hypothesisAuthProviderFixture.mjs'
import test from 'node:test'
import assert from 'node:assert/strict'
import {randomUUID} from 'node:crypto'
import {createHypothesisHttpTransport} from '../../src/lib/hypothesisHttpTransport.js'
import {observedHistoryView,observationListView} from '../../src/lib/hypothesisObservations.js'
import {createHypothesisHandler} from '../../supabase/qualification/hypothesis-assessments/handler.mjs'
import {createHypothesisStore} from '../../supabase/qualification/hypothesis-assessments/store.mjs'
import {createHypothesisAssessmentClient,hypothesisHistoryView} from '../../src/lib/hypothesisAssessmentClient.js'
import {setup,hold,blocked,q,raw,workerRole} from './fixture.mjs'
import {isolatedWorker} from './isolatedContainer.mjs'
import {syntheticEvaluation} from './syntheticMethod.mjs'
import {assessmentFromEvaluation,runDurableHypothesisWorker,recoverHypothesisRequest} from '../../supabase/qualification/hypothesis-assessments/worker.mjs'
const completeArgs=(v,j,output,request=randomUUID(),session=v.session)=>({p_request:request,p_session:session,p_runtime:v.runtime,
 p_generation:j.generation_id,p_token:j.lease_token,p_input_hash:j.input_hash,p_implementation:j.implementation_ref,p_output:output})
const output=j=>{const g=JSON.parse(j.input_text);return assessmentFromEvaluation(g,syntheticEvaluation(g))}
const claim=(f,v,request=randomUUID())=>f.claim(v.session,v.runtime,request)
const counts=(f,v)=>f.admin('select (select count(*) from mip_hypothesis.generation_outputs o join mip_hypothesis.generations g on g.id=o.generation_id where g.investigation_id='+q(v.iid)+")||':'||(select count(*) from mip_hypothesis.revisions where investigation_id="+q(v.iid)+")||':'||(select count(*) from mip_hypothesis.generation_requests r join mip_hypothesis.generations g on g.id=r.generation_id where g.investigation_id="+q(v.iid)+" and r.operation='worker_complete')")
const rpcSql=(f,name,args)=>'select mip_hypothesis.'+name+'('+f.signatures[name].map(k=>q(args[k])).join(',')+')'
const method=v=>({revision:v.method,implementation:v.implementation,model_version:'none',evaluate:syntheticEvaluation})
const options=(f,v,extra={})=>({rpc:f.rpc,journal:f.journal(v.session),runtime:v.runtime,session:v.session,method:method(v),requestId:randomUUID,sha256:f.sha,...extra})
async function childRun(f,v,{key,crash}={}) {
 const child=isolatedWorker(),journal=f.journal(v.session)
 let recoveryKey=null,errorSeen=false
 return await new Promise((resolve,reject)=>{
  const timer=setTimeout(()=>{child.kill();reject(Error('mip_worker_test_timeout'))},30000)
  child.on('message',async message=>{
   if(message.done){clearTimeout(timer);child.kill();resolve({state:message.state,key:message.recovery_key,errorSeen});return}
   try {
    let result
    if(message.kind==='journal')result=await journal[message.name](...message.args)
    else {
     recoveryKey=message.name+':'+message.args.p_request
     if(crash==='before_complete_commit'&&message.name==='worker_complete') {
      const held=await hold(f.db,rpcSql(f,message.name,message.args),workerRole)
      child.kill();await held.finish(false);return
     }
     result=await f.rpc(message.name,message.args)
     if((crash==='after_complete_commit'&&message.name==='worker_complete')||(crash==='after_claim_commit'&&message.name==='worker_claim')) {child.kill();return}
    }
    child.send({reply:true,id:message.id,result})
   } catch {errorSeen=true;child.send({reply:true,id:message.id,error:'mip_test_rpc_denied'})}
  })
  child.on('exit',()=>{clearTimeout(timer);resolve({state:'terminated',key:recoveryKey,errorSeen})})
  child.send({start:true,runtime:v.runtime,session:v.session,method:{revision:v.method,implementation:v.implementation,model_version:'none'},...(key?{key}:{})})
 })
}
