// Hold an actual disposable database transaction and expose only its PID, not query output.
export async function hold(db,sql,role='postgres') {
 guard()
 const child=spawn('psql',['-X','-qAt','-v','ON_ERROR_STOP=1','-h','127.0.0.1','-p','5432','-U','postgres','-d',db],
  {env:{PATH:process.env.PATH,PGPASSWORD:'mip-disposable-ci-only',PGOPTIONS:'-c statement_timeout=20000 -c lock_timeout=15000'},stdio:['pipe','pipe','pipe']})
 let out='',err='';child.stdout.on('data',x=>out+=x);child.stderr.on('data',x=>err+=x)
 let exitResolve
 const exited=new Promise(resolve=>exitResolve=resolve);child.on('exit',code=>exitResolve(code))
 child.stdin.write('set session authorization '+role+';begin;'+sql+";select 'READY:'||pg_backend_pid();\n")
 const deadline=Date.now()+10000
 while(!out.includes('READY:')) {
  if(err.includes('ERROR')||Date.now()>deadline){child.kill('SIGKILL');throw Error('mip_hold_failed')}
  await new Promise(r=>setTimeout(r,10))
 }
 return {pid:Number(out.match(/READY:(\d+)/)[1]),finish:async(commit=true)=>{child.stdin.end(commit?'commit;\n':'rollback;\n');if(await exited)throw Error('mip_hold_commit_failed')}}
}
export async function blocked(f,pid) {
 const deadline=Date.now()+5000
 while(Date.now()<deadline) {
  if(await f.admin('select count(*) from pg_stat_activity where '+pid+'=any(pg_blocking_pids(pid))')!=='0')return
  await new Promise(r=>setTimeout(r,20))
 }
 throw Error('mip_expected_serialization_wait')
}

import {spawn} from 'node:child_process'
export function guard(){
 if(process.env.GITHUB_ACTIONS!=='true'||process.env.MIP_DISPOSABLE_POSTGRES!=='comparison-qualification')
  throw Error('mip_disposable_environment_required')
}
export const quote=v=>v===null?'null':"'"+String(typeof v==='object'?JSON.stringify(v):v).replaceAll("'","''")+"'"
export function raw(database,sql){
 guard()
 return new Promise((resolve,reject)=>{
  const env=Object.fromEntries(Object.entries(process.env).filter(([k])=>!k.startsWith('PG')))
  Object.assign(env,{PGPASSWORD:'mip-disposable-ci-only',PGOPTIONS:'-c statement_timeout=20000 -c lock_timeout=15000',PGCONNECT_TIMEOUT:'5'})
  const child=spawn('psql',['-X','-qAt','-v','ON_ERROR_STOP=1','-v','VERBOSITY=verbose','-h','127.0.0.1','-p','5432','-U','postgres','-d',database],{env,stdio:['pipe','pipe','pipe']})
  let out='',err='';child.stdout.on('data',x=>out+=x);child.stderr.on('data',x=>err+=x)
  child.on('error',()=>reject(Error('mip_database_unavailable')))
  child.on('exit',code=>{
   if(code){
    const state=err.match(/ERROR:\s+([0-9A-Z]{5}):/)?.[1]??'unknown'
    const code=err.match(/ERROR:\s+(?:[0-9A-Z]{5}:\s+)?(mip_[a-z_]+)/)?.[1]
    const object=err.match(/permission denied for (?:table|schema|function) ([a-z_0-9]+)/)?.[1]
    const contexts=[...err.matchAll(/(?:PL\/pgSQL|SQL) function ([a-z_0-9.]+)/g)].map(x=>x[1]).filter(x=>/^(mip_|comparison_)/.test(x)).slice(0,5).join('_').replaceAll('.','_')
    const failure=Error((code??'mip_database_denied_'+state+(object?'_'+object:''))+(contexts?'_via_'+contexts:''))
    failure.code=state // Preserve only PostgreSQL SQLSTATE for the trusted handler; no query/payload text.
    reject(failure)
   }
   else resolve(out.trim())
  })
  child.stdin.end(sql)
 })
}
const names=new Set(['configuration','issue','journal_runtime','journal_put','journal_get','worker_claim','worker_complete','worker_fail','producer_enqueue','capture_delta','reconciliation','stage_review','release_isolated','release_public'])
export function transport(database,role){
 if(!/^[a-z_0-9]+$/.test(role))throw Error('mip_role_invalid')
 return async(name,args)=>{
  if(!names.has(name))throw Error('mip_rpc_invalid')
  const result=await raw(database,'set session authorization '+role+';select to_jsonb(mip_identity.'+name+'('+args.map(quote).join(',')+'));').catch(e=>{throw Error(e.message+'_'+name)})
  return result?JSON.parse(result):null
 }
}

